package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.FirstReleaseVO;

class FirstReleaseValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of first release of observed issue")
  void test_first_release_value_holder_assign_plain_value() {
    Object holder = new Object();
    FirstReleaseValueHolder<Object> value = new FirstReleaseValueHolder<>(holder);
    Assertions.assertSame(holder, value.firstRelease("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getFirstReleaseValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getFirstRelease().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.firstReleaseNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getFirstReleaseValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getFirstRelease().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of first release of observed issue")
  void test_first_release_value_holder_assign_value_object() {
    Object holder = new Object();
    FirstReleaseValueHolder<Object> value = new FirstReleaseValueHolder<>(holder);
    FirstReleaseVO vo = FirstReleaseVO.from("one");
    Assertions.assertFalse(value.getFirstReleaseValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.firstRelease(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getFirstReleaseValue().orElseThrow());
    Assertions.assertSame(holder, value.firstRelease(Optional.empty()));
    Assertions.assertFalse(value.getFirstReleaseValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.firstRelease(Optional.of(vo)));
    Assertions.assertSame(vo, value.getFirstReleaseValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of first release of observed issue against the original")
  void test_first_release_value_holder_read() {
    Object holder = new Object();
    FirstReleaseValueHolder<Object> value = new FirstReleaseValueHolder<>(holder);
    FirstReleaseVO vo = FirstReleaseVO.from("one");
    FirstReleaseVO other = FirstReleaseVO.from("one");
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getFirstReleaseValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readFirstRelease(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readFirstRelease(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.firstRelease(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readFirstRelease(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readFirstRelease(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of first release of observed issue")
  void test_first_release_value_holder_unset() {
    Object holder = new Object();
    FirstReleaseValueHolder<Object> value = new FirstReleaseValueHolder<>(holder);
    FirstReleaseVO vo = FirstReleaseVO.from("one");
    value.firstRelease(vo);
    Assertions.assertSame(holder, value.unsetFirstReleaseIfMatches("firstRelease_other"));
    Assertions.assertTrue(value.getFirstReleaseValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetFirstReleaseIfMatches("firstRelease"));
    Assertions.assertFalse(value.getFirstReleaseValue().isPresent(),
        "The field name must clear the value");
    value.firstRelease(vo);
    Assertions.assertSame(holder, value.unsetFirstRelease());
    Assertions.assertFalse(value.getFirstReleaseValue().isPresent(), "Unset must clear the value");
  }
}
